WITH dim_totals AS (SELECT p.region, p.city, COUNT(*) AS rows_total, MAX(src.revenue) AS max_revenue, ROUND(AVG(src.units), 2) AS avg_units, GROUPING_ID() AS gid FROM store_sales src INNER JOIN stores p ON src.store_id = p.id GROUP BY GROUPING SETS ((p.region, p.city), (p.region), ())) SELECT region, rows_total, max_revenue, avg_units, gid, CASE WHEN region RLIKE '^(Central|West)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS region_zone FROM dim_totals ORDER BY avg_units DESC NULLS LAST
